-- ---------------------------------------------------------------------
-- Verse-id lookup helper as a temporary view scoped to this txn.
-- canon edition only — every reference in this migration resolves there.
-- ---------------------------------------------------------------------
CREATE TEMP VIEW _s110_verse_lookup AS
SELECT b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v
  JOIN chapters c ON v.chapter_id = c.id
  JOIN books    b ON c.book_id    = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug = 'canon';

-- ---------------------------------------------------------------------
