  ('matthew', 27, 51, 'isaiah', 25, 7, '*He will destroy in this mountain the face of the covering cast over all people.*'),
  ('matthew', 27, 51, 'daniel', 12, 2, 'The Tanakh-resurrection anchor.'),
  ('matthew', 27, 51, 'ezekiel', 37, 1, 'The valley-of-dry-bones.'),
  ('matthew', 27, 51, '1-corinthians', 15, 20, 'The firstfruits substance.'),
  ('matthew', 27, 51, 'revelation', 20, 4, 'The first-resurrection substance.'),
  ('matthew', 27, 51, 'isaiah', 26, 19, '*Thy dead men shall live.*'),
  ('matthew', 27, 51, 'hosea', 13, 14, '*I will ransom them from the power of the grave.*'),
  ('matthew', 27, 51, '1-thessalonians', 4, 13, '*The dead in Messiah shall rise first.*'),
  ('matthew', 27, 51, 'john', 5, 25, '*The hour ... when the dead shall hear the voice of the Son of Elohim.*'),
  ('matthew', 28, 18, 'matthew', 10, 5, '*Go ... rather to the lost sheep of the house of Yashar''el (Israel)* — `lost-sheep-mission-scope`.'),
  ('matthew', 28, 18, 'matthew', 15, 24, '*I am not sent but unto the lost sheep of the house of Yashar''el (Israel)*.'),
  ('matthew', 28, 18, 'matthew', 4, 14, 'Galilee-of-the-goyim per Yeshayahu 9:1-2 — the territories-of-the-scattered-seed.'),
  ('matthew', 28, 18, 'isaiah', 11, 11, 'The substantial-recovery-of-the-remnant from-the-four-corners.'),
  ('matthew', 28, 18, 'ezekiel', 37, 15, 'The two-sticks-united substance.'),
  ('matthew', 28, 18, 'jeremiah', 31, 31, 'The new-covenant heart-Torah substance.'),
  ('matthew', 28, 18, 'hosea', 1, 10, '*In the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim.*'),
  ('matthew', 28, 18, 'romans', 9, 25, 'The Pauline-citation of Hosheia 1:10.'),
  ('matthew', 28, 18, 'acts', 1, 8, '*Witnesses unto me ... unto the uttermost part of the earth.*'),
  ('matthew', 28, 18, 'acts', 2, 5, 'The substantial-Pentecost-substance — *out of every nation under heaven* + the substantial-scattered-Yahudim-substance.'),
  ('matthew', 28, 18, 'acts', 11, 19, 'The substantial-substance-of-the-Gospel-going-to-the-Yahudim-substance-only first.'),
  ('matthew', 28, 18, 'matthew', 24, 14, 'The substantial-gospel-of-the-kingdom-preached-for-a-witness-unto-all-nations.'),
  ('matthew', 28, 18, 'matthew', 26, 13, '*Wheresoever this gospel shall be preached in the whole world.*'),
  ('matthew', 28, 18, 'james', 1, 1, '*The twelve tribes which are scattered abroad.*'),
  ('matthew', 28, 18, '1-peter', 1, 1, '*The strangers scattered throughout Pontos, Galatia, Kappadokia, Asia, and Bithunia.*'),
  ('matthew', 28, 18, '2-samuel', 7, 23, 'The substantial-substance the Father walked-out the substantial-redemption-of-Yashar''el.'),
  ('matthew', 28, 18, 'daniel', 7, 13, '*Dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him* per Red Line #12.'),
  ('matthew', 28, 18, 'micah', 4, 1, 'The nations flow-unto-the-mountain-of-Yahuah''s-house.'),
  ('matthew', 28, 18, 'isaiah', 56, 1, 'The substantial-Tanakh-substance the sons-of-the-stranger-joined-to-Yahuah-substance — the scattered-coming-home-substance.'),
  ('matthew', 28, 18, 'matthew', 1, 1, 'The Matthean-bookend opening with the substantial-genealogy.'),
  ('matthew', 28, 19, 'acts', 2, 38, '*Be baptized every one of you in the name of Yahusha HaMashiach.*'),
  ('matthew', 28, 19, 'acts', 8, 16, '*They were baptized in the name of the Lord Yahusha.*'),
  ('matthew', 28, 19, 'acts', 10, 48, '*He commanded them to be baptized in the name of the Lord.*'),
  ('matthew', 28, 19, 'acts', 19, 5, '*They were baptized in the name of the Lord Yahusha.*'),
  ('matthew', 28, 19, 'romans', 6, 3, '*Baptized into Yahusha HaMashiach.*'),
  ('matthew', 28, 19, 'galatians', 3, 27, '*Baptized into Messiah (Christ) have put on Messiah.*'),
  ('matthew', 28, 19, 'matthew', 1, 21, '*Thou shalt call his name Yahusha (Jesus): for he shall save his people from their sins.*'),
  ('matthew', 28, 19, 'matthew', 1, 23, '*They shall call his name Immanuel ... Elohim (God) with us.*'),
  ('matthew', 28, 19, 'matthew', 3, 16, 'The substantial-baptism-substance + the Father-Son-Spirit-substance.'),
  ('matthew', 28, 19, 'matthew', 17, 1, 'The substantial-transfiguration-substance per `transfiguration-formless-formed-nature-of-god-visible`.'),
  ('matthew', 28, 19, 'john', 14, 16, 'The substantial-Comforter-substance — Father-Son-Spirit.'),
  ('matthew', 28, 19, 'john', 14, 26, 'The Ruach-substance-comes-in-the-name-of-the-Son.'),
  ('matthew', 28, 19, 'john', 17, 5, 'The substantial-substance-of-the-substantial-relational-substance.'),
  ('matthew', 28, 19, 'john', 17, 11, 'The substantial-substance-of-the-substantial-relational-substance.'),
  ('matthew', 28, 19, 'john', 17, 21, 'The substantial-substance-of-the-substantial-relational-substance.'),
  ('matthew', 28, 19, '1-corinthians', 8, 6, '*One Elohim, the Father ... one Lord Yahusha (Jesus) HaMashiach.*'),
  ('matthew', 28, 19, 'philippians', 2, 6, 'The substantial-substance-of-the-incarnation-substance + the substantial-name above-every-name-substance.'),
  ('matthew', 28, 20, 'matthew', 5, 17, 'The substantial-anti-antinomian-declaration of-the-Sermon — the substantial-bookend.'),
  ('matthew', 28, 20, 'matthew', 7, 21, 'The substantial-*Lord, Lord* + *I never knew you* + *anomia* substance.'),
  ('matthew', 28, 20, 'matthew', 22, 36, 'The substantial-Shema + Vayikra 19:18 + *on these two commandments hang all the law and the prophets*.'),
  ('matthew', 28, 20, 'john', 2, 3, 'The 1234-of-Truth + *if we keep his commandments*.'),
  ('matthew', 28, 20, 'john', 5, 2, '*This is the love of Elohim, that we keep his commandments.*'),
  ('matthew', 28, 20, 'john', 14, 15, '*If ye love me, keep my commandments.*'),
  ('matthew', 28, 20, 'john', 14, 21, '*He that hath my commandments, and keepeth them, he it is that loveth me.*'),
  ('matthew', 28, 20, 'jeremiah', 31, 31, 'The new-covenant heart-Torah-substance.'),
  ('matthew', 28, 20, 'ezekiel', 36, 26, 'The new-heart + the substantial-Ruach-substance + *cause you to walk in my statutes*.'),
  ('matthew', 28, 20, 'revelation', 14, 12, '*They that keep the commandments of Elohim, and the faith of Yahusha.*'),
  ('matthew', 28, 20, 'revelation', 22, 14, '*Blessed are they that do his commandments.*'),
  ('matthew', 28, 20, 'james', 2, 14, '*Faith without works is dead.*'),
  ('matthew', 28, 20, 'romans', 3, 31, '*Do we then make void the law through faith? Elohim forbid: yea, we establish the law.*'),
  ('matthew', 28, 1, 'mark', 16, 1, 'The Markan-parallel.'),
  ('matthew', 28, 1, 'luke', 24, 1, 'The Lukan-parallel.'),
  ('matthew', 28, 1, 'john', 20, 1, 'The Yochanan-narrative.'),
  ('matthew', 28, 1, 'psalms', 16, 10, 'The Tanakh-Resurrection-anchor.'),
  ('matthew', 28, 1, 'psalms', 22, 22, 'The substantial-vindication-substance — *I will declare thy name unto my brethren*.'),
  ('matthew', 28, 1, 'hosea', 6, 2, 'The third-day-substance.'),
  ('matthew', 28, 1, 'jonah', 1, 17, 'The substantial-three-days-and-three-nights pre-figuration.'),
  ('matthew', 28, 1, '1-corinthians', 15, 20, 'The firstfruits substance.'),
  ('matthew', 28, 1, 'acts', 2, 24, 'The substantial-Kefa-Tehillim-16-citation.'),
  ('matthew', 28, 1, 'acts', 13, 33, 'The substantial-Paul-Tehillim-16-citation.'),
  ('matthew', 28, 1, 'romans', 1, 4, '*Declared to be the Son of Elohim with power ... by the resurrection from the dead.*'),
  ('matthew', 28, 1, 'matthew', 27, 55, 'The women-witnessing-the-Cross.'),
  ('matthew', 28, 1, 'matthew', 27, 61, 'The women-witnessing-the-burial.'),
  ('matthew', 28, 1, 'john', 20, 11, 'Miryam Magdalene-substance.'),
  ('matthew', 28, 1, 'john', 19, 25, 'The substantial-women-at-the-Cross.'),
  ('matthew', 28, 1, 'proverbs', 31, 10, 'The substantial-Tanakh-virtuous-woman-substance.'),
  ('matthew', 28, 1, 'luke', 8, 1, 'The substantial-women-supporting-the-ministry-substance.'),
  ('matthew', 1, 1, 'genesis', 5, 1, '*This is the book of the generations of Adam* — Matthew''s opening phrase deliberately echoes the LXX of Gen 5:1, signaling Adamic-toledot continuity at the head of the New Testament canon.'),
  ('matthew', 1, 1, 'luke', 3, 23, 'The biological-Adamic-descent genealogy through Miryam''s (Mary''s) line — the framework''s double-witness coordination with Matthew''s legal-Davidic genealogy through Yoseph (Joseph).'),
  ('matthew', 1, 6, '1-samuel', 16, 1, 'The anointing of David — the founding moment of the kingship-line the genealogy traces.'),
  ('matthew', 1, 6, '2-samuel', 11, 1, 'The David-Bathsheba-Uriah narrative — the source of Matthew''s naming-by-Uriah construction.'),
  ('matthew', 1, 11, '2-kings', 23, 34, 'Yo''achaz (Jehoahaz) deposed by Pharaoh — the kings between Josias (Yoshiyahu) and the deportation, the unstable monarchy collapsing toward the captivity.'),
  ('matthew', 1, 11, 'jeremiah', 22, 24, 'The Yahuah-pronouncement against Konyahu (Jeconiah) — *no man of his seed shall prosper, sitting upon the throne of David* — addressed in framework reading through Yoseph''s (Joseph''s) legal adoption of Yahusha (Jesus), bypassing the Jeconiah-blood-curse while preserving the legal-Davidic claim.'),
  ('matthew', 1, 18, 'luke', 1, 26, 'The annunciation to Miryam (Mary) — the parallel narrative of the Spirit-conception.'),
  ('matthew', 1, 19, 'deuteronomy', 22, 23, 'The Torah''s penalty provision for adultery in an espoused virgin — the legal exposure Yoseph''s (Joseph''s) quiet divorce would have shielded Miryam (Mary) from.'),
  ('matthew', 1, 19, 'deuteronomy', 24, 1, 'The bill of divorcement provision — Yoseph''s (Joseph''s) Torah-righteous response operates within this framework.'),
  ('matthew', 1, 20, 'genesis', 28, 12, 'Ya''aqov''s (Jacob''s) dream at Beth-el — the angel-in-a-dream as the Tanakh-pattern divine-instruction medium.'),
  ('matthew', 1, 20, 'genesis', 37, 5, 'The patriarch Yoseph''s (Joseph''s) own dreams — Matthew''s Yoseph (Joseph) carries the Tanakh-Yoseph''s (Joseph''s) dream-receiving role.'),
  ('matthew', 1, 20, 'daniel', 2, 19, '*The secret revealed unto Daniel in a night vision* — the prophetic precedent for dream-revelation of Yahuah''s (God''s) plan.'),
  ('matthew', 1, 20, '2-samuel', 7, 12, '*Thou son of David* invokes the Davidic-covenant promise the angel is now naming Yoseph (Joseph) as the carrier of.'),
  ('matthew', 1, 24, 'luke', 2, 7, '*And she brought forth her firstborn son, and wrapped him in swaddling clothes* — Luke''s parallel of the firstborn naming.'),
  ('matthew', 1, 24, 'exodus', 13, 2, '*Sanctify unto me all the firstborn* — the Torah''s firstborn-consecration sets the framework for Yahusha (Jesus) as firstborn.'),
  ('matthew', 1, 24, 'colossians', 1, 15, '*The firstborn of every creature ... the firstborn from the dead* — the apostolic firstborn-Christology grounded in the Torah firstborn pattern.'),
  ('matthew', 1, 24, 'colossians', 1, 18, '*The firstborn of every creature ... the firstborn from the dead* — the apostolic firstborn-Christology grounded in the Torah firstborn pattern.'),
  ('matthew', 2, 5, 'micah', 5, 2, 'The Old Testament prophetic source — Beth-lehem Ephratah as the birth-locale of the *ruler in Yashar''el (Israel); whose goings forth have been from of old, from everlasting.*'),
  ('matthew', 2, 5, '1-samuel', 16, 1, 'Beth-lehem as David''s birthplace and the locale of his anointing — the seed-line geography.'),
  ('matthew', 2, 5, '1-samuel', 16, 4, 'Beth-lehem as David''s birthplace and the locale of his anointing — the seed-line geography.'),
  ('matthew', 2, 5, 'ruth', 4, 11, '*Do thou worthily in Ephratah, and be famous in Beth-lehem* — the blessing on Boaz at the kinsman-redeemer marriage that produces the line of David.'),
  ('matthew', 2, 11, 'psalms', 72, 10, '*The kings of Tarshish and of the isles shall bring presents: the kings of Sheba and Seba shall offer gifts. Yea, all kings shall fall down before him: all nations shall serve him* — the Davidic-king psalm prefiguring the gift-bringing of the Magi.'),
  ('matthew', 2, 11, 'exodus', 30, 34, 'The frankincense in the holy incense of the tabernacle — the priestly significance of the second gift.'),
  ('matthew', 2, 11, 'psalms', 45, 8, '*All thy garments smell of myrrh, and aloes, and cassia* — the Messianic-bridegroom psalm naming myrrh as a Messianic-royal attribute. The myrrh-gift also foreshadows the burial-preparation of Yahusha (Jesus) — myrrh appears at his birth and at his death (John 19:39).'),
  ('matthew', 2, 15, 'exodus', 4, 22, '*Yashar''el (Israel) is my son, even my firstborn ... Let my son go, that he may serve me* — the Old Testament identification of Yashar''el (Israel) as Yahuah''s (God''s) firstborn son; Matthew''s recapitulation reading hears this verse standing behind Hosea 11:1.'),
  ('matthew', 2, 22, 'isaiah', 9, 1, '*The land of Zevulun (Zebulun), and the land of Naphtali ... the people that walked in darkness have seen a great light* — the Galilee-of-the-Gentiles prophecy that Matthew 4:13-16 will explicitly cite, prepared by Matthew 2:22-23''s settling in the Galilee.'),
  ('matthew', 3, 4, 'leviticus', 11, 21, 'The Torah-permission for eating locusts — Yochanan''s (John''s) diet is Torah-observant, marking him as a Torah-righteous prophet inside the covenant standard.'),
  ('matthew', 3, 11, 'joel', 2, 28, '*I will pour out my Ruach (Spirit) upon all flesh* — the prophetic Spirit-outpouring fulfilled at Pentecost (Acts 2).'),
  ('matthew', 3, 11, 'ezekiel', 36, 25, '*I will sprinkle clean water upon you ... A new heart also will I give you ... I will put my Ruach (Spirit) within you* — the water-Spirit-new-heart prophetic complex Yochanan (John) is naming.'),
  ('matthew', 3, 11, 'malachi', 3, 1, '*Who may abide the day of his coming? ... for he is like a refiner''s fire* — the fire-baptism Yochanan (John) names is Malachi''s refiner''s fire; the sifting that the gathering carries.'),
  ('matthew', 3, 15, 'psalms', 40, 7, '*Lo, I come ... I delight to do thy will, O my Elohim (God): yea, thy Torah is within my heart* — the Messianic-Psalm anticipation of the Servant fulfilling all the Father''s will, quoted by Hebrews 10:7.'),
  ('matthew', 3, 15, 'isaiah', 53, 11, '*By his knowledge shall my righteous servant justify many* — the Servant-Song''s *righteous* anticipation of the Messiah''s righteousness, into which the immersion is the public entry.'),
  ('matthew', 4, 6, 'psalms', 91, 11, 'The OT source the devil quotes — with the qualifier *to keep thee in all thy ways* (v.11) omitted.'),
  ('matthew', 4, 6, 'psalms', 91, 14, '*Because he hath set his love upon me, therefore will I deliver him* — another qualifier-verse in the Psalm establishing the covenant-faithfulness condition of the promise.'),
  ('matthew', 4, 11, 'hebrews', 1, 14, '*Are they not all ministering spirits, sent forth to minister for them who shall be heirs of salvation* — the standing angelic-ministry role; Matt 4:11 is the unforced fulfillment of what the devil had wanted to manipulate as a sign-test at vv.5-7.'),
  ('matthew', 4, 11, '1-kings', 19, 5, 'Eliyahu (Elijah) ministered to by an angel after the contest at Carmel — the Tanakh-pattern of angelic ministry to the prophet after spiritual conflict.'),
  ('matthew', 4, 17, 'matthew', 3, 2, 'The verbally-identical preaching-formula of Yochanan (John) the Immerser; the deliberate continuity of message between Yochanan (John) and Yahusha (Jesus).'),
  ('matthew', 4, 17, 'daniel', 2, 44, '*In the days of these kings shall the Elohim (God) of heaven set up a kingdom, which shall never be destroyed* — the Tanakh-source of the everlasting kingdom Yahusha (Jesus) names as *at hand.*'),
  ('matthew', 4, 17, 'daniel', 7, 13, 'The Son-of-Adam-kingdom-transfer prophecy (kaph-comparative preserved); the kingdom-at-hand is this kingdom.'),
  ('matthew', 4, 23, 'isaiah', 35, 4, '*Then the eyes of the blind shall be opened ... the lame man leap as an hart* — the Messianic-credential prophecy authenticated by Yahusha''s (Jesus''s) healing ministry; Yahusha (Jesus) cites this credential himself at Matt 11:2-5 when Yochanan (John) sends from prison to ask.'),
  ('matthew', 4, 23, 'isaiah', 61, 1, '*He hath sent me to bind up the brokenhearted, to proclaim liberty to the captives, and the opening of the prison to them that are bound* — the Messianic-mission summary Yahusha (Jesus) will explicitly quote at Luke 4:18-19 in his Natsareth (Nazareth) synagogue declaration.'),
  ('matthew', 5, 3, 'isaiah', 57, 15, '*I dwell in the high and holy place, with him also that is of a contrite and humble spirit* — the Tanakh-anchor of the *anawim*-posture.'),
  ('matthew', 5, 3, 'isaiah', 66, 2, '*To this man will I look, even to him that is poor and of a contrite spirit, and trembleth at my word* — the prophetic-marker of the gathered remnant.'),
  ('matthew', 5, 4, 'ezekiel', 9, 4, '*Set a mark upon the foreheads of the men that sigh and that cry for all the abominations* — the framework reading: mourning is the prophetic-cry against abominations; the mark of Yahuah (the LORD) falls on this posture.'),
  ('matthew', 5, 4, 'isaiah', 61, 2, '*To comfort all that mourn; to appoint unto them that mourn in Tsion (Zion), to give unto them beauty for ashes, the oil of joy for mourning* — the Yeshayahu (Isaiah) 61 comfort-promise that fills the Beatitude.'),
  ('matthew', 5, 6, 'psalms', 42, 1, '*As the hart panteth after the water brooks, so panteth my soul after thee, O Elohim (God)* — the Tanakh-hunger-and-thirst posture.'),
  ('matthew', 5, 6, 'jeremiah', 23, 5, '*In his days Yahudah (Judah) shall be saved, and Yashar''el (Israel) shall dwell safely: and this is his name whereby he shall be called, Yahuah Tsidkenu (THE LORD OUR RIGHTEOUSNESS)* — the Messianic-source of the *tsedaqah* the hungering ones are filled with.'),
  ('matthew', 5, 8, 'psalms', 24, 3, '*Who shall ascend into the hill of Yahuah (the LORD)? or who shall stand in his holy place? He that hath clean hands, and a pure heart* — the Tanakh-anchor of the pure-heart ascent.'),
  ('matthew', 5, 8, 'jeremiah', 31, 33, '*I will put my law in their inward parts, and write it in their hearts* — the new-heart promise that produces the *pure in heart*.'),
  ('matthew', 5, 8, 'ezekiel', 36, 26, '*A new heart also will I give you* — the new-heart promise companion.'),
  ('matthew', 5, 17, 'isaiah', 42, 21, '*Yahuah (the LORD) is well pleased for his righteousness'' sake; he will magnify the law, and make it honourable* — the Messianic-mission as Torah-magnification, not Torah-abolition; Yahusha (Jesus) walks Yeshayahu (Isaiah) 42:21.'),
  ('matthew', 5, 17, 'luke', 16, 17, '*It is easier for heaven and earth to pass, than one tittle of the law to fail* — the Lukan parallel of Matt 5:18, confirming the framework reading.'),
  ('matthew', 5, 19, 'james', 2, 10, '*Whosoever shall keep the whole law, and yet offend in one point, he is guilty of all* — Ya''aqov''s (James''s) affirmation of the unity of the commandments; the breaking of *even the least* is named gravely.'),
  ('matthew', 5, 48, '1-peter', 1, 15, '*But as he which hath called you is holy, so be ye holy in all manner of conversation; Because it is written, Be ye holy; for I am holy* — Kefa''s (Peter''s) NT carry-forward of the same Torah-pattern.'),
  ('matthew', 6, 1, 'deuteronomy', 15, 7, 'The Torah''s command on generous alms-giving — the practice Yahusha (Jesus) is correcting the motive on, not the practice itself.'),
  ('matthew', 6, 1, 'leviticus', 19, 9, 'The gleaning-rights of the poor — the Torah''s social-economy in which alms-giving is embedded.'),
  ('matthew', 6, 1, 'deuteronomy', 24, 19, 'The forgotten-sheaf law for the stranger, fatherless, and widow — Tanakh-substance of alms-giving.'),
  ('matthew', 6, 1, 'psalms', 41, 1, '*Blessed is he that considereth the poor* — the wisdom-stream''s alms-substance.'),
  ('matthew', 6, 1, 'proverbs', 19, 17, '*He that hath pity upon the poor lendeth unto Yahuah (the LORD)* — second wisdom-stream alms-substance witness.'),
  ('matthew', 6, 1, 'matthew', 5, 16, '*Let your light so shine before men, that they may see your good works, and glorify your Father* — the apparent-tension verse the framework resolves by motive-distinction.'),
  ('matthew', 6, 5, '1-kings', 8, 22, 'Shlomo''s (Solomon''s) temple-dedication prayer — the Tanakh''s longest public-prayer record, demonstrating that public prayer is not what Matt 6:5-6 prohibits.'),
  ('matthew', 6, 5, 'acts', 1, 14, 'The apostolic-community gathered prayer — the New Testament''s pattern of corporate prayer in the disciples Yahusha (Jesus) is now teaching.'),
  ('matthew', 6, 5, 'acts', 2, 42, '*They continued stedfastly in the apostles'' doctrine and fellowship, and in breaking of bread, and in prayers* — the gathered prayer as a defining mark of the early assembly.'),
  ('matthew', 6, 5, 'acts', 4, 24, 'The first assembly''s gathered prayer at the release of Kepha (Peter) and Yochanan (John).'),
  ('matthew', 6, 5, 'john', 11, 41, 'Yahusha''s (Jesus''s) own public prayer at the raising of El''azar (Lazarus) — *I said it, that they may believe that thou hast sent me* — naming the public posture explicitly.'),
  ('matthew', 6, 5, 'psalms', 139, 1, '*Thou understandest my thought afar off ... there is not a word in my tongue, but, lo, O Yahuah (LORD), thou knowest it altogether* — the Father-knows-before-the-asking Tanakh substance the lock at Matt 6:8 rests on.'),
  ('matthew', 6, 9, 'isaiah', 63, 16, '*Thou, O Yahuah (LORD), art our father, our redeemer* — first Tanakh-Father-address anchor.'),
  ('matthew', 6, 9, 'isaiah', 64, 8, '*But now, O Yahuah (LORD), thou art our Father* — second Tanakh-Father-address anchor.'),
  ('matthew', 6, 9, 'deuteronomy', 32, 6, '*Is not he thy Father that hath bought thee?* — third Tanakh-Father-address anchor.'),
  ('matthew', 6, 11, 'exodus', 16, 4, 'The manna-pattern — *that I may prove them, whether they will walk in my law, or no* — the daily-bread Tanakh-substance.'),
  ('matthew', 6, 11, 'proverbs', 30, 8, '*Give me neither poverty nor riches; feed me with food convenient for me* — the wisdom-stream''s daily-bread petition.'),
  ('matthew', 6, 11, 'matthew', 4, 4, '*Man shall not live by bread alone, but by every word that proceedeth out of the mouth of Elohim (God)* — Yahusha''s (Jesus''s) wilderness-citation of Deuteronomy 8:3; the daily-bread carries both physical and Torah-bread registers.'),
  ('matthew', 6, 13, 'matthew', 4, 1, 'The wilderness-temptation Yahusha (Jesus) just walked — the petition is for the Father''s protective leading the disciples will need as they walk what their Master walked.'),
  ('matthew', 6, 13, '1-corinthians', 10, 13, '*Elohim (God) is faithful, who will not suffer you to be tempted above that ye are able* — the apostolic confirmation of the petition''s substance.'),
  ('matthew', 6, 13, 'james', 1, 13, '*Elohim (God) cannot be tempted with evil, neither tempteth he any man* — the apostolic clarification that the petition is not about *do not cause us to be tempted.*'),
  ('matthew', 6, 16, 'leviticus', 23, 27, 'The Yom Kippur fast — *ye shall afflict your souls* — the Torah''s central fast-command.'),
  ('matthew', 6, 16, 'joel', 1, 14, 'The prophet''s call for a national fast — *sanctify ye a fast, call a solemn assembly* — Tanakh-substance of corporate fasting.'),
  ('matthew', 6, 16, 'isaiah', 58, 6, '*Is not this the fast that I have chosen? to loose the bands of wickedness ... to deal thy bread to the hungry* — the Tanakh-charter of the kingdom-citizens fast; substance-correction beneath the Matt 6:16-18 form-correction.'),
  ('matthew', 6, 16, 'matthew', 4, 2, 'Yahusha''s (Jesus''s) own forty-day wilderness fast — the immediate framework-prefigure.'),
  ('matthew', 6, 20, 'proverbs', 11, 4, '*Riches profit not in the day of wrath: but righteousness delivereth from death* — the wisdom-stream futility-of-earth-treasure.'),
  ('matthew', 6, 20, 'proverbs', 23, 4, '*Riches certainly make themselves wings; they fly away as an eagle toward heaven* — second wisdom-stream witness.'),
  ('matthew', 6, 20, 'psalms', 49, 16, 'The futility-of-riches psalm — *when he dieth he shall carry nothing away.*'),
  ('matthew', 6, 20, 'luke', 12, 33, 'The Lukan parallel of Matt 6:19-21 — *provide yourselves bags which wax not old, a treasure in the heavens that faileth not.*'),
  ('matthew', 6, 22, 'proverbs', 22, 9, '*He that hath a bountiful eye (tov-ayin) shall be blessed; for he giveth of his bread to the poor* — the Hebrew-idiom anchor; good-eye = generous heart.'),
  ('matthew', 6, 22, 'proverbs', 23, 6, '*Eat thou not the bread of him that hath an evil eye (ra-ayin)* — the contrasting idiom; evil-eye = stingy/grasping heart.'),
  ('matthew', 6, 22, 'deuteronomy', 15, 9, '*Thine eye be evil against thy poor brother* — the same evil-eye idiom in Torah-context, naming the stinginess-toward-the-poor that the Torah forbids; locks the Hebrew-idiom reading of Matt 6:22-23.'),
  ('matthew', 6, 22, 'proverbs', 28, 22, '*He that hasteth to be rich hath an evil eye* — fourth wisdom-stream witness of the evil-eye = stingy-heart idiom.'),
  ('matthew', 6, 24, 'exodus', 20, 3, '*Thou shalt have no other gods before me* — the first commandment ruling out competing masters categorically.'),
  ('matthew', 6, 24, 'deuteronomy', 6, 4, '*Hear, O Yashar''el (Israel): Yahuah Eloheinu (The LORD our God) is one Yahuah (LORD): And thou shalt love Yahuah Elohayka (the LORD thy God) with all thine heart* — the Shema''s whole-heart standard the dual-allegiance breaks.'),
  ('matthew', 6, 24, '1-kings', 18, 21, '*How long halt ye between two opinions?* — Eliyahu (Elijah)''s Carmel-confrontation as the Tanakh-pattern of the forced-choice Matt 6:24 articulates.'),
  ('matthew', 6, 26, 'psalms', 147, 9, '*He giveth to the beast his food, and to the young ravens which cry* — the Father''s covenant-care for the creatures.'),
  ('matthew', 6, 26, 'job', 38, 4, 'The creation-care testimony from the whirlwind — the architectural-witness to the Father''s sustaining of every creature.'),
  ('matthew', 6, 26, 'psalms', 104, 10, 'The comprehensive creation-care psalm — *He causeth the grass to grow for the cattle.*'),
  ('matthew', 6, 33, '1-kings', 3, 11, 'Shlomo''s (Solomon''s) Gibeon-dream — he asked for wisdom rather than wealth, and Yahuah (the LORD) added the wealth; the Tanakh-pattern of *seek first the kingdom, and these things shall be added.*'),
  ('matthew', 6, 33, 'psalms', 37, 4, '*Delight thyself also in Yahuah (the LORD); and he shall give thee the desires of thine heart* — the priority-orientation pattern.'),
  ('matthew', 6, 33, 'matthew', 5, 6, '*Blessed are they which do hunger and thirst after righteousness: for they shall be filled* — the Beatitude that Matt 6:33 names in practice.'),
  ('matthew', 7, 1, 'leviticus', 19, 17, '*Thou shalt in any wise rebuke thy neighbour, and not suffer sin upon him ... thou shalt love thy neighbour as thyself* — the Torah''s command to rebuke combined with the love-of-neighbor command.'),
  ('matthew', 7, 1, 'john', 7, 24, '*Judge not according to the appearance, but judge righteous judgment* — Yahusha''s (Jesus''s) explicit reframing that locks Matt 7:1 as a kind-of-judgment-correction, not abolition of judgment.'),
  ('matthew', 7, 6, 'proverbs', 23, 9, '*Speak not in the ears of a fool: for he will despise the wisdom of thy words* — the wisdom-stream''s discrimination of audience; consistent with the pearls-before-swine principle.'),
  ('matthew', 7, 6, 'matthew', 10, 14, '*Whosoever shall not receive you, nor hear your words, when ye depart out of that house or city, shake off the dust of your feet* — Yahusha''s (Jesus''s) instruction to the disciples on the same discrimination-of-audience pattern.'),
  ('matthew', 7, 11, 'luke', 11, 13, '*How much more shall your heavenly Father give the Holy Spirit to them that ask him?* — Lukan parallel; specifies *good things* as the Ruach HaKodesh (Holy Spirit).'),
  ('matthew', 7, 11, 'jeremiah', 31, 33, '*I will put my law in their inward parts, and write it in their hearts* — the new-heart promise the Spirit-gift enables.'),
  ('matthew', 7, 11, 'ezekiel', 36, 26, '*A new heart also will I give you ... and cause you to walk in my statutes* — the Spirit-empowered Torah-walking promise the good gift produces.'),
  ('matthew', 7, 13, 'isaiah', 10, 20, 'The remnant-of-Yashar''el (Israel) Tanakh-pattern — only a remnant returns.'),
  ('matthew', 7, 13, 'zechariah', 13, 8, '*Two parts therein shall be cut off and die; but the third shall be left therein* — the third-part remnant; explicit numerical-minority structure.'),
  ('matthew', 7, 13, 'zephaniah', 3, 12, '*I will also leave in the midst of thee an afflicted and poor people, and they shall trust in the name of Yahuah (the LORD). The remnant of Yashar''el (Israel) shall not do iniquity* — the remnant defined by Torah-walking.'),
  ('matthew', 7, 13, 'luke', 13, 23, '*Strive to enter in at the strait gate: for many, I say unto you, will seek to enter in, and shall not be able* — Lukan parallel that intensifies the *few* of Matt 7:14.'),
  ('matthew', 7, 15, 'ezekiel', 22, 27, '*Her princes in the midst thereof are like wolves ravening the prey* — the prophet''s identification of the leadership-system as wolves in the Tanakh-pattern.'),
  ('matthew', 7, 15, 'acts', 20, 29, 'Paul''s warning to the Ephesian elders — *grievous wolves enter in among you, not sparing the flock. Also of your own selves shall men arise, speaking perverse things* — the apostolic confirmation of the false-prophets-among-the-gathering pattern.'),
  ('matthew', 7, 24, 'exodus', 24, 7, '*All that Yahuah (the LORD) hath said will we do, and be obedient (na''aseh v''nishma)* — the do-and-hear Tanakh-pattern Matt 7:24-27 walks.'),
  ('matthew', 7, 24, 'deuteronomy', 32, 4, '*He is the Rock, his work is perfect* — the Tanakh''s foundation-rock identification of Yahuah (the LORD).'),
  ('matthew', 7, 24, 'psalms', 18, 2, '*Yahuah (the LORD) is my rock, and my fortress* — the foundation-rock prayer-substance.'),
  ('matthew', 7, 24, 'james', 1, 22, '*But be ye doers of the word, and not hearers only ... whoso looketh into the perfect law of liberty, and continueth therein, he being not a forgetful hearer, but a doer of the work, this man shall be blessed in his deed* — Ya''aqov''s (James''s) apostolic restatement of the Matt 7:24-27 hearer-AND-doer standard.'),
  ('matthew', 8, 1, 'leviticus', 13, 45, 'The leper''s required posture under the Torah''s purity-architecture; the defiling-condition Yahusha''s (Jesus''s) touch reverses.'),
  ('matthew', 8, 1, 'luke', 17, 11, 'The second-leper episode; Yahusha (Jesus) again directs the cleansed (ten lepers) to *go shew yourselves unto the priests* — same Torah-procedure affirmation.'),
  ('matthew', 8, 5, 'luke', 7, 1, 'The Lukan parallel with the additional detail of the Jewish-elders'' intercession and the centurion''s standing in the Kfar-Nachum (Capernaum) gathering.'),
  ('matthew', 8, 11, 'jeremiah', 31, 8, 'The Yirmeyahu (Jeremiah) 31 gathering-prophecy chapter Matthew has been weaving through the gospel since Matt 2:18.'),
  ('matthew', 8, 17, 'isaiah', 53, 4, 'The direct prophetic source; the Suffering-Servant chapter Matthew applies to the healing ministry.'),
  ('matthew', 8, 17, 'isaiah', 35, 5, 'The Messianic-credential prophecy the healing-ministry authenticates; Yahusha (Jesus) will cite this credential himself at Matt 11:5.'),
  ('matthew', 8, 17, 'matthew', 11, 4, 'The future self-citation of the Isaiah 35 credential when Yochanan (John) the Immerser sends from prison.'),
  ('matthew', 8, 20, 'psalms', 8, 4, '*What is mortal man, that thou art mindful of him? and the son of Adam, that thou visitest him?* — the son-of-Adam Tanakh-substance the title carries.'),
  ('matthew', 8, 20, 'luke', 3, 38, '*Adam, which was the son of Elohim (God)* — the Lukan genealogy''s seed-of-Adam-line-of-promise anchor; the Son of Adam at Matt 8:20 stands in this lineage.'),
  ('matthew', 8, 22, 'exodus', 20, 12, 'The fifth commandment; the Torah-substance the framework preserves; Yahusha (Jesus) is not abolishing parent-honor at Matt 8:22.'),
  ('matthew', 8, 22, 'genesis', 50, 5, '*Let me go up, I pray thee, and bury my father* — the patriarchal-burial Tanakh-pattern.'),
  ('matthew', 8, 22, 'mark', 7, 10, 'Yahusha''s (Jesus''s) explicit defense of the fifth commandment against the *Corban* oral-tradition workaround.'),
  ('matthew', 8, 26, 'psalms', 89, 8, '*Thou rulest the raging of the sea: when the waves thereof arise, thou stillest them* — the Tanakh-creation-authority of Yahuah (the LORD) the Formed exercises in person.'),
  ('matthew', 8, 26, 'psalms', 107, 23, 'The sailors-in-the-storm psalm; *He maketh the storm a calm, so that the waves thereof are still.*'),
  ('matthew', 8, 26, 'job', 38, 8, '*Hitherto shalt thou come, but no further: and here shall thy proud waves be stayed* — the creation-ruling Tanakh-voice the disciples are recognizing.'),
  ('matthew', 8, 26, 'jonah', 1, 5, '*Yonah (Jonah) was gone down into the sides of the ship; and he lay, and was fast asleep* — the Jonah-1 parallel Matt 8:23-27 inverts; the *greater than Yonah (Jonah)* foreshadowing.'),
  ('matthew', 8, 26, 'matthew', 12, 41, '*A greater than Yonah (Jonah) is here* — the future explicit naming of the same foreshadowing.'),
  ('matthew', 8, 29, '1-john', 3, 8, '*For this purpose the Son of Elohim (God) was manifested, that he might destroy the works of the devil* — the apostolic naming of the King''s mission against the principalities; the demons recognize what they are facing.'),
  ('matthew', 8, 29, '2-peter', 2, 4, '*Elohim (God) spared not the angels that sinned, but cast them down to hell, and delivered them into chains of darkness, to be reserved unto judgment* — the bound-angels-reserved-for-judgment architecture; the *time* the demons reference is this appointed judgment.'),
  ('matthew', 8, 29, 'jude', 1, 6, '*And the angels which kept not their first estate ... he hath reserved in everlasting chains under darkness unto the judgment of the great day* — same architecture, same appointed time.'),
  ('matthew', 8, 30, 'leviticus', 11, 7, 'The swine as unclean-animals under Torah-law; the visible-marker that the Gergesene/Gadarene territory was under Hellenistic-Gentile administration, not Torah-walking.'),
