  ('matthew', 9, 2, 'isaiah', 43, 25, '*I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins.* The Yahuah-prerogative the scribes correctly identify as belonging to Elohim (God) alone.'),
  ('matthew', 9, 2, 'psalms', 103, 3, '*Who forgiveth all thine iniquities; who healeth all thy diseases.* The Tanakh-pairing of forgiveness-and-healing that Matt 9:1-8 demonstrates in person.'),
  ('matthew', 9, 6, 'daniel', 7, 13, 'The kaph-comparative *one like the Son of Adam* (incarnation-honoring; harmonized identification is Yahusha (Jesus) himself, the Formed cloud-rider who took on flesh) — the figure to whom all dominion is given; the same figure exercising the forgiveness-prerogative on earth at Matt 9:6.'),
  ('matthew', 9, 6, 'matthew', 28, 18, '*All power is given unto me in heaven and in earth* — the full-disclosure of the authority the Son of Adam already exercised at Matt 9:6.'),
