  ('matthew', 9, 24, 'daniel', 12, 2, '*And many of them that sleep in the dust of the earth shall awake* — the Tanakh''s resurrection-language.'),
  ('matthew', 9, 24, 'isaiah', 26, 19, '*Thy dead men shall live ... Awake and sing, ye that dwell in dust.* The resurrection-prophecy Yahusha (Jesus) carries the present-age-foretaste of at 9:25.'),
  ('matthew', 9, 24, 'john', 11, 11, '*Lazaros (Lazarus) sleepeth; but I go, that I may awake him out of sleep.* The same death-as-sleep vocabulary at the Lazaros-raising.'),
