INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, tier_required, sort_order) SELECT 'eli-eli-lama-sabachthani-the-tehillim-22-citation-and-the-tehillim-22-as-a-whole-substance', 'Eli Eli Lama Sabachthani The Tehillim 22 Citation And The Tehillim 22 As A Whole Substance', '**`eli-eli-lama-sabachthani-the-tehillim-22-citation-and-the-tehillim-22-as-a-whole-substance`** — **FRAMEWORK-MAJOR anchor at Matt 27:46.** The substantial-King-substance cites-the-opening-verse-of-Tehillim (Psalm) 22 substance at-the-substantial-substance-of-the-Cross-substance + the substantial-Tehillim 22-as-a-whole walks-from-suffering-into-vindication-substance. Framework reads — substance is-NOT-the-substantial-substance-of-the-categorical-substance-of-the-Father-substantially-forsaking-the-Son-substance the inherited-Christian-collapse walks; the substance is the substantial-rabbinic-citation-of-the-opening-verse-substance summoning-the-whole-Psalm-substance + the substantial-substance-of-the-Cross-substance walks-the-Tehillim 22 substance comprehensively. 15 members.', sv.verse_id, 'free', 100   FROM _s110_verse_lookup sv  WHERE sv.book_slug = 'matthew' AND sv.chapter_number = 27 AND sv.verse_number = 46 ON CONFLICT (slug) DO NOTHING;
