INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order) SELECT 'gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father', 'Gethsemane Cup Of Suffering And The Sons Substantial Submission To The Father', '**`gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father`** — anchor at Matt 26:36-46. The substantial-Gethsemane substance + the substantial-cup-of-suffering substance per `cup-of-suffering-tanakh-substance` thread (PROPOSED at Matt 20 from S85) + the substantial-Son''s-submission-to-the-Father per the Formless-Formed grid per `nature-of-god-formed-in-flesh` thread. Framework rules out Trinitarian-three-co-equal-persons + modalist-collapse + Arian-created-being; the substantial-Son''s-eternal-submission preserved in incarnation. 16 members.', sv.verse_id, ev.verse_id, 'free', 100   FROM _s110_verse_lookup sv, _s110_verse_lookup ev  WHERE sv.book_slug = 'matthew' AND sv.chapter_number = 26 AND sv.verse_number = 36    AND ev.book_slug = 'matthew' AND ev.chapter_number = 26 AND ev.verse_number = 46 ON CONFLICT (slug) DO NOTHING;
