INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order) SELECT 'great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance', 'Great Commission All Nations As Territories Of The Scattered Seed Not Categorical Three Categories Substance', '**`great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance`** — **FRAMEWORK-MAJOR anchor at Matt 28:18-20.** The substantial-Great-Commission-substance walks the substantial-territorial-extension-of-the-mission-scope-substance NOT-categorical-Three-Categories-#3-substance per Red Line #7 + `lost-sheep-mission-scope` thread (DUAL-FRAMEWORK-MAJOR-anchored at Matt 10:5-6 + Matt 15:24). The substantial-*panta ta ethnē*-substance is the substantial-territorial-substance the substantial-scattered-seed-of-both-houses-of-Yashar''el (Israel) is-substantially-among-substance per Yeshayahu 11:11-12 + Yechezk''el 37:15-28 + the substantial-Tanakh-substance. Framework rules out the inherited-Christian-collapse of-the-Great-Commission-as-categorical-Gentile-inclusion-substance. 21 members.', sv.verse_id, ev.verse_id, 'free', 100   FROM _s110_verse_lookup sv, _s110_verse_lookup ev  WHERE sv.book_slug = 'matthew' AND sv.chapter_number = 28 AND sv.verse_number = 18    AND ev.book_slug = 'matthew' AND ev.chapter_number = 28 AND ev.verse_number = 20 ON CONFLICT (slug) DO NOTHING;
-- WARNING: thread 'heart-defilement-and-the-mouth-substance' has no resolvable anchor — skipping
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order) SELECT 'heart-torah-not-abolition', 'Heart Torah Not Abolition', 'Yahusha (Jesus) at Matt 5:17-19 preemptively denies the antinomian misreading of his ministry. He has NOT come to destroy the law or the prophets; he has come to FILL them up to their intended substance. Until heaven and earth pass, one jot or one tittle does not pass from the law. The pulpit that teaches the breaking of even the least commandment is named LEAST in the kingdom of heaven. Matthew 5:19 is the New Testament companion of 1 John 2:3-4 — both verses say the same thing in different grammar: keeping the commandments — and teaching others to keep them — is the proof of knowing him. The thread carries the load-bearing anti-antinomian declaration of the Sermon on the Mount, tied back to the Tanakh''s continuing-Torah witnesses and forward to every NT passage that reaffirms the Torah''s standing.', sv.verse_id, ev.verse_id, 'free', 100   FROM _s110_verse_lookup sv, _s110_verse_lookup ev  WHERE sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 17    AND ev.book_slug = 'matthew' AND ev.chapter_number = 5 AND ev.verse_number = 19 ON CONFLICT (slug) DO NOTHING;
-- WARNING: thread 'herod-as-edomite-usurper' has no resolvable anchor — skipping
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, tier_required, sort_order) SELECT 'his-blood-be-on-us-and-on-our-children-system-not-people-and-the-yom-kippur-blood-substance', 'His Blood Be On Us And On Our Children System Not People And The Yom Kippur Blood Substance', '**`his-blood-be-on-us-and-on-our-children-system-not-people-and-the-yom-kippur-blood-substance`** — anchor at Matt 27:25. The substantial-Yerushalayim-crowd-at-the-substantial-Sanhedrin-leadership-moment-substance the substantial-substance walked-out + the substantial-substance the framework''s-system-not-people-posture per `_COMMENTARY_SUMMATION.md` §VII + Red Line #9''s-Jew-hate-never-justifiable-substance + the substantial-Yom Kippur-blood-substance walking-substantially-into-the-substantial-Cross-blood-substance per Zekharyah 12:10''s-look-on-him-whom-they-pierced-substance + the substantial-substance-of-the-surviving-third per `_COMMENTARY_SUMMATION.md` §V. 14 members.', sv.verse_id, 'free', 100   FROM _s110_verse_lookup sv  WHERE sv.book_slug = 'matthew' AND sv.chapter_number = 27 AND sv.verse_number = 25 ON CONFLICT (slug) DO NOTHING;
