INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order) SELECT 'last-supper-this-is-my-body-this-is-my-blood-of-the-new-testament', 'Last Supper This Is My Body This Is My Blood Of The New Testament', '**`last-supper-this-is-my-body-this-is-my-blood-of-the-new-testament`** — anchor at Matt 26:26-29. The substantial-Pesach (Passover)-meal substance the King-substance walks-out + the substantial-*this is my body* + *this is my blood of the new testament* substance the substantial-Yirmeyahu (Jeremiah) 31:31-34''s-new-covenant-substance + the substantial-marriage-of-the-Lamb-substance pre-figured. Framework reads the substance carefully — NOT-Roman-Catholic-transubstantiation, NOT-Reformation-memorial-only; the substantial-Pesach-meal-substance + the King-substance invests-with-the-substantial-Pesach-lamb-fulfillment-substance. 18 members.', sv.verse_id, ev.verse_id, 'free', 100   FROM _s110_verse_lookup sv, _s110_verse_lookup ev  WHERE sv.book_slug = 'matthew' AND sv.chapter_number = 26 AND sv.verse_number = 26    AND ev.book_slug = 'matthew' AND ev.chapter_number = 26 AND ev.verse_number = 29 ON CONFLICT (slug) DO NOTHING;
