INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order) SELECT 'lord-lord-and-torahlessness', 'Lord Lord And Torahlessness', 'Yahusha (Jesus) at Matt 7:21-23 names the institutional-Christian antinomian-gospel community in advance: many at the judgment-day will confess him as Lord twice over, claim active supernatural-ministry under his name (prophesying, casting out demons, doing wonderful works), and hear in return: I NEVER KNEW YOU; depart from me, ye workers of ANOMIA — torahlessness. The Greek anomia is literally without-Torah. The credentials are real-but-insufficient; the verbal-confession is explicit-but-insufficient; the supernatural-acts are evident-but-insufficient. The doing-of-the-Father''s-will (= heart-Torah-walking) is what separates the wheat from the unfruitful-wheat at the post-harvest sifting. This is the most-load-bearing NT verse for the contrary-to-Torah test of 1 John 2:3-4 applied to the modern Judaizer movement (institutional Christianity). The thread connects v.21-23 to the Tanakh false-prophet diagnostics (Deut 13, Deut 18), the post-harvest sifting (Ezekiel 20:33-38, Matt 25:31-46, Matt 13:30), the wheat-vs-unfruitful-wheat distinction (the wheat can be sifted into fruitful and unfruitful after the harvest), the grace-that-can-be-lost stream (Hosea 7:13, Ezekiel 18, Ezekiel 33), and the contrary-to-Torah test master-filter (1 John 2:3-4).', sv.verse_id, ev.verse_id, 'free', 100   FROM _s110_verse_lookup sv, _s110_verse_lookup ev  WHERE sv.book_slug = 'matthew' AND sv.chapter_number = 7 AND sv.verse_number = 21    AND ev.book_slug = 'matthew' AND ev.chapter_number = 7 AND ev.verse_number = 23 ON CONFLICT (slug) DO NOTHING;
