INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order) SELECT 'parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness', 'Parable Of The Talents Stewardship And The Unprofitable Servant Cast Into Outer Darkness', '**`parable-of-the-talents-stewardship-and-the-unprofitable-servant-cast-into-outer-darkness`** — anchor at Matt 25:14-30. The substantial-substance-of-the-substance-of-the-stewardship-substance + the unprofitable-servant-substance walking the `grace-and-the-opportunity-that-can-be-lost` thread (FREE-TIER-CANDIDATE) at the substantial-substance-of-the-most-substantial-substance — the unprofitable-servant has-been-given-the-talent + has-been-named-as-a-servant + has-been-cast-into-outer-darkness for-the-failure-of-stewardship-substance. 14 members.', sv.verse_id, ev.verse_id, 'free', 100   FROM _s110_verse_lookup sv, _s110_verse_lookup ev  WHERE sv.book_slug = 'matthew' AND sv.chapter_number = 25 AND sv.verse_number = 14    AND ev.book_slug = 'matthew' AND ev.chapter_number = 25 AND ev.verse_number = 30 ON CONFLICT (slug) DO NOTHING;
