INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order) SELECT 'paul-and-the-wresting-of-his-letters', 'Paul And The Wresting Of His Letters', 'Peter writing about Paul names the wresting of Paul''s letters by the unlearned and unstable as a known phenomenon producing destruction. The institutional-Christian collapse of Paul''s letters into an antinomian gospel is the wresting Peter warned about, two thousand years downstream. The framework reads Paul as harmonizing with the King''s own teaching at Matt 7:21, not contradicting him. The Romans 10:9-10 confession-and-belief is the journey''s beginning, not its full completion; the King at Matt 7:21 names the doing-of-the-Father''s-will as the entry-criterion at the judgment-day; the two are not in conflict when Paul is read with the rest of the canon harmonized. The thread connects Peter''s warning to the specific Pauline passages most wrested (Romans 10:9-10, Romans 3-4 on faith and works, Galatians 3 on the law as schoolmaster, Hebrews 7-10 on the priesthood and the sacrifice, Ephesians 2:8-9 on grace through faith) and to Paul''s own counter-articulations (Romans 3:31 on establishing the law, Romans 7:12 on the holy and just and good law, Romans 8:4 on the righteousness of the law fulfilled in those who walk after the Spirit, Galatians 5:6 on faith working through love, Hebrews 8:10 on the new covenant as Torah written on the heart).', sv.verse_id, ev.verse_id, 'free', 100   FROM _s110_verse_lookup sv, _s110_verse_lookup ev  WHERE sv.book_slug = '2-peter' AND sv.chapter_number = 3 AND sv.verse_number = 15    AND ev.book_slug = '2-peter' AND ev.chapter_number = 3 AND ev.verse_number = 17 ON CONFLICT (slug) DO NOTHING;
