INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 1, 'The actual deportation of Yahudah (Judah) to Babylon — the historical anchor of Matthew''s hinge.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'babylonian-captivity-hinge'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 11    AND tv.book_slug = '2-kings' AND tv.chapter_number = 24 AND tv.verse_number = 14    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
