INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 3, 'The sheep-and-goats judgment scene — separated by what they DID, not what they said; the practical-walking diagnostic Matt 7:21 articulates in proposition.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'lord-lord-and-torahlessness'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 7 AND sv.verse_number = 21    AND tv.book_slug = 'matthew' AND tv.chapter_number = 25 AND tv.verse_number = 31    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 4, '*If there arise among you a prophet, or a dreamer of dreams, and giveth thee a sign or a wonder, And the sign or the wonder come to pass ... thou shalt not hearken unto the words of that prophet* — the Tanakh false-prophet diagnostic; signs-and-wonders are not the proof; the Torah-fidelity is.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'lord-lord-and-torahlessness'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 7 AND sv.verse_number = 22    AND tv.book_slug = 'deuteronomy' AND tv.chapter_number = 13 AND tv.verse_number = 1    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 5, '*That prophet, which shall presume to speak a word in my name, which I have not commanded him to speak ... shall die* — the false-prophet-in-the-Name diagnostic.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'lord-lord-and-torahlessness'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 7 AND sv.verse_number = 22    AND tv.book_slug = 'deuteronomy' AND tv.chapter_number = 18 AND tv.verse_number = 20    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 6, '*Such are false apostles, deceitful workers, transforming themselves into the apostles of HaMashiach (Christ). And no marvel; for Satan himself is transformed into an angel of light* — the apostolic confirmation that supernatural-credentials can attend false ministers.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'lord-lord-and-torahlessness'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 7 AND sv.verse_number = 22    AND tv.book_slug = '2-corinthians' AND tv.chapter_number = 11 AND tv.verse_number = 13    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
