INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 9, '*For the mystery of iniquity (anomia, torahlessness) doth already work* — the apostolic naming of the *anomia* — the mystery of TORAHLESSNESS — operating in the present age.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'lord-lord-and-torahlessness'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 7 AND sv.verse_number = 23    AND tv.book_slug = '2-thessalonians' AND tv.chapter_number = 2 AND tv.verse_number = 7    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
