INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 1, '*And Mosheh (Moses) called Oshea (Hoshea) the son of Nun, Yahoshua (Joshua)* — the Old Testament parent-name to *Yahusha* is *Yahoshua* (the same root, the same divine-name component), and the renaming itself is theological.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'name-restoration-yahusha'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'numbers' AND tv.chapter_number = 13 AND tv.verse_number = 16    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 2, '*Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved* — the name is the announcement and the means.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'name-restoration-yahusha'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'acts' AND tv.chapter_number = 4 AND tv.verse_number = 12    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 3, '*Sing unto Elohim (God), sing praises to his name: extol him that rideth upon the heavens by his name Yah, and rejoice before him* — the short form *Yah* preserved in the Old Testament as the explicit object of praise; the *Yah* in *Yahusha* is the name praised here.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'name-restoration-yahusha'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'psalms' AND tv.chapter_number = 68 AND tv.verse_number = 4    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 4, 'The commissioning of Yahoshua (Joshua) to lead the entry into the land — the first-fruits typology of the Messianic ingathering.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'name-restoration-yahusha'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'joshua' AND tv.chapter_number = 1 AND tv.verse_number = 1    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 5, '*Wherefore Elohim (God) also hath highly exalted him, and given him a name which is above every name* — the apostolic recognition that the name carries the authority.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'name-restoration-yahusha'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'philippians' AND tv.chapter_number = 2 AND tv.verse_number = 9    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
