INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 3, '*Thou canst not see my face: for there shall no man see me, and live* — the formless-infinite Father not seen by mortal eyes; the Formed in flesh is what is seen in Matt 1:23.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'nature-of-god-formed-in-flesh'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 23    AND tv.book_slug = 'exodus' AND tv.chapter_number = 33 AND tv.verse_number = 20    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
