INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 5, '*Yahuah (the LORD) appeared unto him in the plains of Mamre ... and, lo, three men stood by him* — a theophany of the Formed in pre-incarnate form, prefiguring the Matt 1:23 incarnation.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'nature-of-god-formed-in-flesh'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 23    AND tv.book_slug = 'genesis' AND tv.chapter_number = 18 AND tv.verse_number = 1    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 6, '*They saw the Elohim (God) of Yashar''el (Israel) ... they saw Elohim (God), and did eat and drink* — the seventy elders see the Formed. The Formless is not what is seen; the Formed is.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'nature-of-god-formed-in-flesh'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 23    AND tv.book_slug = 'exodus' AND tv.chapter_number = 24 AND tv.verse_number = 9    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 7, '*Then shall the Son also himself be subject unto him that put all things under him* — the eternal submission of the Formed to the Formless preserved in the eschaton. The Trinity''s co-equal-persons frame cannot account for the eschatological submission; the framework''s Formless-and-Formed reading carries it natively.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'nature-of-god-formed-in-flesh'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 23    AND tv.book_slug = '1-corinthians' AND tv.chapter_number = 15 AND tv.verse_number = 28    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 8, '*The head of the Messiah (Christ) is Elohim (God)* — the eternal headship of the Father over the Son, preserved through and after the incarnation.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'nature-of-god-formed-in-flesh'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 23    AND tv.book_slug = '1-corinthians' AND tv.chapter_number = 11 AND tv.verse_number = 3    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 1, '*Thou shalt not hate thy brother in thine heart* — the Torah''s heart-substance of the sixth commandment; the oral tradition stopped at the act, the Torah always taught the heart-root.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'oral-tradition-correction-not-torah-supersession'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 21    AND tv.book_slug = 'leviticus' AND tv.chapter_number = 19 AND tv.verse_number = 17    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 3, '*Thou shalt not covet thy neighbour''s wife* — the tenth commandment, naming the heart-coveting that precedes the act of adultery; the Torah already named the heart-substance.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'oral-tradition-correction-not-torah-supersession'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 27    AND tv.book_slug = 'exodus' AND tv.chapter_number = 20 AND tv.verse_number = 17    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 4, '*Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh* — the original marriage-design Yahusha (Jesus) restores; Yahusha (Jesus) will explicitly cite this at Matt 19:4-9 as the framework against the Pharisees'' Devarim (Deuteronomy) 24:1 question.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'oral-tradition-correction-not-torah-supersession'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 31    AND tv.book_slug = 'genesis' AND tv.chapter_number = 2 AND tv.verse_number = 24    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 5, '*Mosheh (Moses) because of the hardness of your hearts suffered you to put away your wives: but from the beginning it was not so* — Yahusha''s (Jesus''s) explicit interpretation of Devarim (Deuteronomy) 24:1 as concession-to-hardness, not Torah-mandate-of-permission.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'oral-tradition-correction-not-torah-supersession'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 31    AND tv.book_slug = 'matthew' AND tv.chapter_number = 19 AND tv.verse_number = 8    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 6, '*If a man vow a vow unto Yahuah (the LORD), or swear an oath to bind his soul with a bond; he shall not break his word, he shall do according to all that proceedeth out of his mouth* — the Torah''s binding-of-oaths standard; Yahusha (Jesus) does not abolish the oath-form but cuts the gradation-evasion-system the oral tradition built.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'oral-tradition-correction-not-torah-supersession'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 33    AND tv.book_slug = 'numbers' AND tv.chapter_number = 30 AND tv.verse_number = 2    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 7, 'Yahusha (Jesus) at Matt 23 indicts the same gradation-system explicitly — *whosoever shall swear by the temple, it is nothing; but whosoever shall swear by the gold of the temple, he is a debtor* — confirming that Matt 5:33-37 is correction of the oral-tradition apparatus, not abolition of all oath-taking.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'oral-tradition-correction-not-torah-supersession'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 33    AND tv.book_slug = 'matthew' AND tv.chapter_number = 23 AND tv.verse_number = 16    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 9, '*Rulers are not a terror to good works ... he beareth not the sword in vain: for he is the minister of Elohim (God), a revenger to execute wrath upon him that doeth evil* — the apostolic confirmation that the judicial-sphere retains the sword and the *lex talionis* function; Matt 5:38-42 is personal-disciple ethic, not abolition of the judicial Torah.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'oral-tradition-correction-not-torah-supersession'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 38    AND tv.book_slug = 'romans' AND tv.chapter_number = 13 AND tv.verse_number = 3    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
