INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 7, 'The new-heart-and-new-spirit Tanakh-promise — the substance that makes the yoke easy.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'yoke-of-torah-easy-vs-pharisaic-burden-heavy'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 11 AND sv.verse_number = 28    AND tv.book_slug = 'ezekiel' AND tv.chapter_number = 36 AND tv.verse_number = 26    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 8, '*His commandments are not grievous* — the apostolic-affirmation of the easy-yoke / not-grievous-burden framework.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'yoke-of-torah-easy-vs-pharisaic-burden-heavy'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 11 AND sv.verse_number = 28    AND tv.book_slug = '1-john' AND tv.chapter_number = 5 AND tv.verse_number = 3    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, 9, 'The load-bearing anti-antinomian declaration of the Sermon — the Torah Yahusha (Jesus) is yoking the disciples to is the Father''s-Torah-internalized.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'yoke-of-torah-easy-vs-pharisaic-burden-heavy'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 11 AND sv.verse_number = 28    AND tv.book_slug = 'matthew' AND tv.chapter_number = 5 AND tv.verse_number = 17    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;

