INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*I do not this for your sakes, O house of Yashar''el (Israel), but for mine holy name''s sake* — the Yah who saves in Matt 1:21 saves for his own name''s sake; the gospel is name-grace, not merit-grace.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'grace-from-name''s-sake'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'ezekiel' AND tv.chapter_number = 36 AND tv.verse_number = 22    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*Not for thy righteousness ... but ... that he may perform the word which Yahuah (the LORD) sware unto thy fathers* — the prior-promise structure that the Messiah''s name announces is now being kept.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'grace-from-name''s-sake'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'deuteronomy' AND tv.chapter_number = 9 AND tv.verse_number = 5    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), 'The sanctification of the Name is *for mine holy name''s sake* — the grace-from-name''s-sake grammar that the *Hallowed be thy name* prayer presupposes.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'grace-from-name''s-sake'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 6 AND sv.verse_number = 9    AND tv.book_slug = 'ezekiel' AND tv.chapter_number = 36 AND tv.verse_number = 22    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*For on that day shall the priest make an atonement for you, to cleanse you, that ye may be clean from all your sins before Yahuah (the LORD)* — the Yom Kippur atonement architecture the forgiveness-petition draws on.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'grace-from-name''s-sake'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 6 AND sv.verse_number = 12    AND tv.book_slug = 'leviticus' AND tv.chapter_number = 16 AND tv.verse_number = 30    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), 'The parable of the unforgiving servant — the king reverses the forgiveness when the servant refuses to extend it; the exact pattern Matt 6:14-15 names in proposition.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'grace-from-name''s-sake'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 6 AND sv.verse_number = 14    AND tv.book_slug = 'matthew' AND tv.chapter_number = 18 AND tv.verse_number = 32    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*I will cause you to pass under the rod ... and I will purge out from among you the rebels* — the post-harvest sifting Yochanan (John) is naming with the *axe is laid unto the root of the trees* image.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'post-harvest-sifting'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 3 AND sv.verse_number = 10    AND tv.book_slug = 'ezekiel' AND tv.chapter_number = 20 AND tv.verse_number = 37    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*His fan is in his hand, and he will throughly purge his floor, and gather his wheat into the garner; but he will burn up the chaff with unquenchable fire* — the chaff-from-wheat sifting that Ezek 20:38 names as the rod-purge of the rebels from among the gathered.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'post-harvest-sifting'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 3 AND sv.verse_number = 12    AND tv.book_slug = 'ezekiel' AND tv.chapter_number = 20 AND tv.verse_number = 38    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*He shall save his people from their sins* maps the Lo-Ammi → sons-of-the-living-Elohim restoration arc onto the naming of Yahusha (Jesus); the *people* he saves is the same people Hosea names.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'hosea' AND tv.chapter_number = 1 AND tv.verse_number = 10    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*He that scattered Yashar''el (Israel) will gather him, and keep him, as a shepherd doth his flock* — the gathering hand named in Jer 31:10 is the *Yah* in Yahusha''s name.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 1 AND sv.verse_number = 21    AND tv.book_slug = 'jeremiah' AND tv.chapter_number = 31 AND tv.verse_number = 10    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), 'The Magi from the east arrive from territories adjacent to the Assyrian-resettlement zones of the scattered northern tribes — the first beat of the gathering, those near where the scattered seed lived hearing the proclamation that had reached their lands through Daniel''s witness.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 2 AND sv.verse_number = 1    AND tv.book_slug = '2-kings' AND tv.chapter_number = 17 AND tv.verse_number = 6    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*And thou Beth-lehem, in the land of Yahudah (Judah)* — the prophetic localization of the Messianic birth to the seed-line town of David. The gathering centers on the seed-line geography.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 2 AND sv.verse_number = 6    AND tv.book_slug = 'micah' AND tv.chapter_number = 5 AND tv.verse_number = 2    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), 'The OT prophetic source — the voice in the wilderness preparing the way of Yahuah (the LORD), in the chapter that opens Yeshayahu''s (Isaiah''s) gathering-and-return prophecies (chs. 40-66).'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 3 AND sv.verse_number = 3    AND tv.book_slug = 'isaiah' AND tv.chapter_number = 40 AND tv.verse_number = 3    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), 'The *Elohim (God) is able of these stones to raise up children unto Avraham (Abraham)* read against Hosea''s *in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim (God)* — the scattered seed in dispersion being recovered as the children of Avraham (Abraham) Yahuah (God) raises up.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 3 AND sv.verse_number = 9    AND tv.book_slug = 'hosea' AND tv.chapter_number = 1 AND tv.verse_number = 10    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*Look unto the rock whence ye are hewn ... look unto Avraham (Abraham) your father, and unto Sarah that bare you* — Yeshayahu''s (Isaiah''s) rock-hewn-lineage image; Avraham (Abraham) himself is the *rock,* and Yahuah (God) recovers the seed from the rock.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 3 AND sv.verse_number = 9    AND tv.book_slug = 'isaiah' AND tv.chapter_number = 51 AND tv.verse_number = 1    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), 'The OT prophetic source — the light dawning on the people of Zevulun (Zebulun) and Naphtali, the scattered-northern-tribe-in-darkness in their tribal territory.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 4 AND sv.verse_number = 15    AND tv.book_slug = 'isaiah' AND tv.chapter_number = 9 AND tv.verse_number = 1    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*Behold, I will send for many fishers, saith Yahuah (the LORD), and they shall fish them* — the prophetic Jeremiah-16 fishers as the agents of the second-Exodus gathering of the scattered seed; Matthew 4:19''s *fishers of men* is the explicit identification of the disciples with the Jer 16 fishers.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 4 AND sv.verse_number = 19    AND tv.book_slug = 'jeremiah' AND tv.chapter_number = 16 AND tv.verse_number = 14    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*I will take the children of Yashar''el (Israel) from among the heathen, whither they be gone, and will gather them on every side, and bring them into their own land* — the early-ministry geographic-scope summary as the beginning of the Ezek 37 gathering.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 4 AND sv.verse_number = 25    AND tv.book_slug = 'ezekiel' AND tv.chapter_number = 37 AND tv.verse_number = 21    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*The meek shall inherit the earth* — the Beatitude is a verbatim quotation of Psalm 37:11; the surrounding context (vv.9-11, 22, 29, 34) is the gathering-and-land-inheritance arc the Beatitude lands on.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 5 AND sv.verse_number = 5    AND tv.book_slug = 'psalms' AND tv.chapter_number = 37 AND tv.verse_number = 9    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*I will sanctify my great name ... when I shall be sanctified in you before their eyes ... For I will take you from among the heathen, and gather you out of all countries* — *Hallowed be thy name* is the gathering-prayer; the Name is sanctified through the gathering of the scattered.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 6 AND sv.verse_number = 9    AND tv.book_slug = 'ezekiel' AND tv.chapter_number = 36 AND tv.verse_number = 23    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), '*Thy kingdom come* — the eschatological-kingdom prayer; the Daniel kingdom-transfer Yahusha (Jesus) refused to short-circuit at Matt 4:8-10.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 6 AND sv.verse_number = 10    AND tv.book_slug = 'daniel' AND tv.chapter_number = 7 AND tv.verse_number = 13    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note) SELECT t.id, x.id, COALESCE((SELECT MAX(sort_order)+1 FROM cross_reference_thread_members WHERE thread_id = t.id), 1), 'The Elohim-of-heaven kingdom that breaks all the kingdoms of the present age — what the kingdom-citizens pray come.'   FROM cross_reference_threads t, cross_references x,        _s110_verse_lookup sv, _s110_verse_lookup tv  WHERE t.slug = 'scattered-seed-gathering'    AND sv.book_slug = 'matthew' AND sv.chapter_number = 6 AND sv.verse_number = 10    AND tv.book_slug = 'daniel' AND tv.chapter_number = 2 AND tv.verse_number = 44    AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual' ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
